layers.vertex:
attribute vec3 aO; attribute float aT, aK, aS; uniform float uTime; varying vec2 vP; varying float vU, vK, vS;
    void main(){
      float u = uTime - aT, life = aK < .5 ? .42 : .4; if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vS = aS;
      if (aK < .5){
        float t = u/.42, S = .78 + .18*(1. - pow(1. - t, 2.));
        float y = .75 + .6*(1. - pow(1. - t, 2.)) + aS*.04;              // rises from the waist to the chest
        vP = position.xy;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, y, -position.y*S), 1.);
      } else {
        vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.22, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.35;
        float S = .24; mv.xy += position.xy*S; vP = position.xy; gl_Position = projectionMatrix*mv;
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK, vS; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float r = length(p); vec3 o;
      if (vK < .5){
        float t = vU/.42, a = atan(p.y, p.x);
        float side = pow(abs(cos(a)), 1.6);                                // two crescents: left and right, open front and back
        float sweep = smoothstep(.0, .35, t);                              // they sweep in from the back
        float prof = pow(side, .7)*smoothstep(1. - sweep, 1. - sweep + .2, side + .001);
        float w = .03*pow(side, 1.2) + .004;                               // thin at the tips, full at the sides
        float d = abs(r - .8), band = exp(-pow(d/w, 2.4)), core = lcore(d, w*.3);
        float f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.5, 1., t));
        o = (uOrange*band*.9 + mix(uGold, vec3(1.), .5)*core*.7)*prof*f*smoothstep(1., .9, r);
      } else {
        float t = vU/.4, f = (vU < .033 ? 1.6 : 1.)*(1. - smoothstep(.45, 1., t)), sc = mix(1.15, 1., smoothstep(0., .15, t));
        vec2 q = p*sc; float d;
        if (0. < .5) d = min(seg(q, vec2(0., -.5), vec2(0., .5)), seg(q, vec2(-.5, .08), vec2(.5, .08)));   // Rage: cross
        else { vec2 a = abs(q);                                                                                  // Bulwark: shield outline
               float sh = q.y > -.05 ? max(a.x - .42, q.y - .45) : length(vec2(q.x/.42, (q.y + .05)/.55)) - 1.;
               d = abs(q.y > -.05 ? sh : sh*.42); }
        float line = exp(-pow(d/.05, 2.)), core = lcore(d, .015);
        o = (uOrange*line + mix(uGold, vec3(1.), .6)*core*.9)*f*smoothstep(1., .85, r);
      }
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
